import { Component, useEffect, useMemo, useRef, useState } from 'react';
import { BrowserRouter, Link, NavLink, Route, Routes, useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import { Area, AreaChart, Radar, RadarChart, PolarAngleAxis, PolarGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Activity, AlertCircle, ArrowLeft, ArrowRight, BarChart3, Bell, Brain, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, Download, FileText, Flame, GraduationCap, HelpCircle, Home, ListChecks, LoaderCircle, Menu, MessageCircle, Pencil, Play, Plus, RotateCcw, Search, Send, Settings as SettingsIcon, Sparkles, Target, Trash2, Trophy, Upload, X, Zap } from 'lucide-react';
import { storage, collectData, importData, loadProfile, resetStudyMateData } from './services/storage';
import { calculatePersonalization, getAdaptiveDifficulty, buildRecommendationExplanation } from './services/personalizationService';
import { demoAttempts, demoTasks } from './data/demoData';
import { getQuestions, questionBank } from './data/questions';
import { curriculum } from './data/curriculum';
import './App.css';

const navItems = [{ to: '/', label: 'Overview', icon: Home }, { to: '/chat', label: 'AI Tutor', icon: MessageCircle }, { to: '/study-plan', label: 'Study plan', icon: CalendarDays }, { to: '/quiz', label: 'Quiz lab', icon: ListChecks }, { to: '/doubt-solver', label: 'Doubt solver', icon: CircleHelp }, { to: '/analytics', label: 'Analytics', icon: BarChart3 }, { to: '/knowledge-map', label: 'Knowledge map', icon: Brain }];
const defaultMessage = { role: 'ai', text: 'Hi, I\'m your local StudyMate tutor. What should we make clearer today?', time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) };

function Button({ children, variant = 'primary', icon: Icon, className = '', ...props }) { return <motion.button whileTap={{ scale: .97 }} whileHover={{ y: -1 }} className={`button button-${variant} ${className}`} {...props}>{Icon && <Icon size={16} strokeWidth={2} />}{children}</motion.button>; }
function Card({ children, className = '', ...props }) { return <motion.section initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .25 }} className={`card ${className}`} {...props}>{children}</motion.section>; }
function ProgressBar({ value, color = 'indigo' }) { return <div className="progress-track"><motion.div initial={{ width: 0 }} animate={{ width: `${Math.min(100, Math.max(0, value))}%` }} className={`progress-fill ${color}`} /></div>; }
function Badge({ children, tone = 'neutral' }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function SectionHeading({ eyebrow, title, action }) { return <div className="section-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{action}</div>; }
function Modal({ title, children, onClose }) { return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><motion.div initial={{ opacity: 0, scale: .97 }} animate={{ opacity: 1, scale: 1 }} className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onMouseDown={(event) => event.stopPropagation()}><div className="modal-header"><h2 id="modal-title">{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={18} /></button></div>{children}</motion.div></div>; }
function Toast({ message, onClose }) { useEffect(() => { const timer = setTimeout(onClose, 3200); return () => clearTimeout(timer); }, [onClose]); return message ? <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="toast" role="status"><CheckCircle2 size={17} />{message}</motion.div> : null; }
function EmptyState({ icon: Icon = Sparkles, title, text, action }) { return <div className="empty-state"><Icon size={25} /><strong>{title}</strong><p>{text}</p>{action}</div>; }
function download(name, content, type = 'application/json') { const url = URL.createObjectURL(new Blob([content], { type })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = name; anchor.click(); URL.revokeObjectURL(url); }

function AppShell({ profile, children }) {
  const [collapsed, setCollapsed] = useState(false); const [mobileOpen, setMobileOpen] = useState(false); const [menuOpen, setMenuOpen] = useState(false); const location = useLocation(); const navigate = useNavigate();
  const initials = (profile.name || 'S').split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
  return <div className={`app-shell ${collapsed ? 'sidebar-collapsed' : ''}`}><aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}><div className="brand"><div className="brand-mark"><Sparkles size={18} /></div><span>StudyMate <b>AI</b></span></div><div className="workspace-switcher"><div className="avatar avatar-small">{initials}</div><div className="workspace-name"><strong>{profile.name}</strong><small>{profile.exam} preparation</small></div><ChevronDown size={15} /></div><nav className="nav-list">{navItems.map(({ to, label, icon: Icon }) => <NavLink key={to} to={to} end={to === '/'} onClick={() => setMobileOpen(false)} className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}><Icon size={18} /><span>{label}</span></NavLink>)}</nav><div className="sidebar-bottom"><NavLink to="/settings" className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}><SettingsIcon size={18} /><span>Settings</span></NavLink><div className="sidebar-tip"><Zap size={16} /><div><strong>Local-first mode</strong><small>No account required</small></div></div><button className="collapse-button" aria-label="Collapse sidebar" onClick={() => setCollapsed(!collapsed)}><ChevronLeft size={16} /></button></div></aside>{mobileOpen && <button className="mobile-scrim" aria-label="Close menu" onClick={() => setMobileOpen(false)} />}<div className="main-area"><header className="topbar"><button className="mobile-menu" aria-label="Open menu" onClick={() => setMobileOpen(true)}><Menu size={21} /></button><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={14} /><strong>{navItems.find((item) => item.to === location.pathname)?.label || 'StudyMate'}</strong></div><div className="topbar-actions"><label className="global-search"><Search size={16} /><input aria-label="Search" placeholder="Search anything" onKeyDown={(event) => event.key === 'Enter' && navigate('/quiz')} /><kbd>⌘ K</kbd></label><button className="icon-button" aria-label="Notifications"><Bell size={18} /></button><div className="profile-control"><button className="profile-trigger" aria-label="Open profile menu" onClick={() => setMenuOpen(!menuOpen)}><span className="avatar">{initials}</span><ChevronDown size={15} /></button>{menuOpen && <div className="popover profile-menu"><strong>{profile.name}</strong><small>{profile.exam} learner</small><button onClick={() => navigate('/settings')}><SettingsIcon size={15} /> Account settings</button><button onClick={() => navigate('/onboarding')}><RotateCcw size={15} /> Update profile</button></div>}</div></div></header><main className="page-content"><AnimatePresence mode="wait"><motion.div key={location.pathname} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .2 }}>{children}</motion.div></AnimatePresence></main></div></div>;
}

function useAppData() { const [profile, setProfile] = useState(loadProfile); const [tasks, setTasks] = useState(() => storage.get('tasks', demoTasks)); const [attempts, setAttempts] = useState(() => storage.get('attempts', demoAttempts)); const [sessions, setSessions] = useState(() => storage.get('focus-sessions', [])); const [toast, setToast] = useState(''); const save = (key, value, setter) => { setter(value); storage.set(key, value); }; const personalization = useMemo(() => calculatePersonalization({ profile, tasks, attempts, studySessions: sessions, diagnostic: storage.get('diagnostic', null), questions: questionBank }), [profile, tasks, attempts, sessions]); return { profile, setProfile, tasks, setTasks: (value) => save('tasks', value, setTasks), attempts, setAttempts: (value) => save('attempts', value, setAttempts), sessions, setSessions: (value) => save('focus-sessions', value, setSessions), personalization, toast, notify: setToast }; }

function Dashboard({ data }) {
  const { profile, tasks, setTasks, attempts, personalization, notify } = data; const navigate = useNavigate(); const completed = tasks.filter((task) => task.done).length; const days = Math.max(0, Math.ceil((new Date(profile.examDate) - new Date()) / 86400000)); const toggle = (id) => { setTasks(tasks.map((task) => task.id === id ? { ...task, done: !task.done, completedAt: !task.done ? new Date().toISOString() : null } : task)); notify('Recommendation updated from your task progress.'); }; const [why, setWhy] = useState(false);
  return <div><div className="page-intro"><div><span className="eyebrow">PERSONAL STUDY OS</span><h1>Good morning, {profile.name.split(' ')[0]} <span className="wave">✦</span></h1><p>Small, focused sessions compound into exam-day confidence.</p></div><Button icon={Plus} onClick={() => navigate('/study-plan')}>Plan a session</Button></div><div className="hero-grid"><Card className="welcome-card"><div><Badge tone="teal">LOCAL PERSONALIZATION</Badge><h2>Your next move is clear.</h2><p>{personalization.nextAction}. Your current readiness is <strong>{personalization.overall}%</strong>.</p><Button icon={ArrowRight} onClick={() => navigate('/chat')}>Ask your tutor</Button></div><div className="hero-orbit"><div className="orbit-ring ring-one" /><div className="orbit-ring ring-two" /><div className="orbit-core"><Brain size={28} /><span>{personalization.overall}%</span><small>readiness</small></div></div></Card><Card className="countdown-card"><div className="card-topline"><span>Exam countdown</span><Target size={18} /></div><strong className="countdown-number">{days}<small> days</small></strong><p>{profile.exam} preparation window</p><div className="countdown-line"><span>Plan coverage</span><span>{Math.min(100, personalization.overall + 8)}%</span></div><ProgressBar value={personalization.overall + 8} color="teal" /></Card></div><div className="stat-grid"><StatCard label="Study target" value={`${personalization.dailyTarget}h`} meta="personalized daily" icon={Clock3} tone="indigo" /><StatCard label="Tasks complete" value={`${completed}/${tasks.length}`} meta="this plan" icon={CheckCircle2} tone="amber" /><StatCard label="Current streak" value={`${Math.min(99, 3 + completed)} days`} meta="keep showing up" icon={Flame} tone="orange" /><StatCard label="Avg. score" value={`${attempts.length ? Math.round(attempts.reduce((sum, a) => sum + a.score, 0) / attempts.length) : personalization.overall}%`} meta="from local attempts" icon={Activity} tone="teal" /></div><div className="content-grid"><Card className="chart-card"><SectionHeading eyebrow="RECOMMENDED NEXT" title={personalization.nextAction} action={<button className="text-button" onClick={() => setWhy(!why)}>{why ? 'Hide reason' : 'Why this recommendation?'} <ChevronDown size={14} /></button>} /><ProgressBar value={personalization.overall} /><p className="recommendation-copy">Weak subjects: {personalization.weakSubjects.join(', ') || 'Keep building your baseline.'}. Recommended difficulty: <strong>{personalization.recommendedDifficulty}</strong>.</p>{why && <div className="explanation-panel"><Sparkles size={16} />{buildRecommendationExplanation(personalization)}</div>}</Card><Card className="focus-card"><SectionHeading eyebrow="TODAY'S FOCUS" title="Keep the chain going" action={<button className="text-button" onClick={() => navigate('/study-plan')}>Manage tasks</button>} /><div className="task-progress"><div className="focus-ring"><span>{completed}/{tasks.length}</span></div><div><strong>{tasks.length - completed ? `${tasks.length - completed} tasks left` : 'All tasks complete'}</strong><p>Tap a task to mark progress.</p></div></div><div className="task-list">{tasks.slice(0, 4).map((task) => <button className={`task-row ${task.done ? 'done' : ''}`} key={task.id} onClick={() => toggle(task.id)}><span className="task-check">{task.done && <Check size={13} />}</span><span className="task-info"><strong>{task.title}</strong><small>{task.subject} · {task.minutes || 30} min</small></span><ArrowRight size={15} /></button>)}</div></Card></div><div className="quick-actions"><div><span className="eyebrow">MAKE IT COUNT</span><h2>Start where you are</h2></div><div className="action-row"><Button variant="secondary" icon={MessageCircle} onClick={() => navigate('/chat')}>Ask AI</Button><Button variant="secondary" icon={Upload} onClick={() => navigate('/doubt-solver')}>Upload notes</Button><Button variant="secondary" icon={ListChecks} onClick={() => navigate('/quiz')}>Start quiz</Button><Button variant="secondary" icon={GraduationCap} onClick={() => navigate('/diagnostic')}>Take diagnostic</Button></div></div></div>;
}
function StatCard({ label, value, meta, icon: Icon, tone }) { return <Card className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={19} /></div><div><span>{label}</span><strong>{value}</strong><small>{meta}</small></div></Card>; }

function Onboarding({ data }) { const navigate = useNavigate(); const [step, setStep] = useState(0); const [form, setForm] = useState(data.profile); const [error, setError] = useState(''); const steps = ['About you', 'Target', 'Study style']; const subjects = ['Mathematics', 'Physics', 'Chemistry', 'Biology', 'Quantitative Aptitude', 'General Studies', 'Science']; const update = (key, value) => setForm({ ...form, [key]: value }); const save = () => { if (!form.name.trim() || !form.examDate || !form.subjects.length) return setError('Add your name, exam date, and at least one subject.'); data.setProfile(form); storage.set('profile', form); navigate('/'); }; return <div className="onboarding-wrap"><Link to="/" className="brand onboarding-brand"><div className="brand-mark"><Sparkles size={18} /></div><span>StudyMate <b>AI</b></span></Link><Card className="onboarding-card"><div className="onboarding-header"><Badge tone="indigo">PERSONALIZE YOUR SPACE</Badge><h1>Let’s make your study time count.</h1><p>A few details help the local engine build a plan that fits your actual life.</p></div><div className="stepper">{steps.map((label, index) => <div className={`step ${index <= step ? 'active' : ''}`} key={label}><span>{index + 1}</span><small>{label}</small></div>)}</div>{error && <div className="form-error"><AlertCircle size={15} />{error}</div>}{step === 0 && <div className="form-grid"><label className="field full"><span>What should we call you?</span><input autoFocus value={form.name} onChange={(event) => update('name', event.target.value)} placeholder="Your name" /></label><label className="field"><span>Target exam</span><select value={form.exam} onChange={(event) => update('exam', event.target.value)}>{['JEE', 'NEET', 'CAT', 'UPSC', 'CBSE Board', 'Custom'].map((exam) => <option key={exam}>{exam}</option>)}</select></label><label className="field"><span>Exam date</span><input type="date" value={form.examDate} onChange={(event) => update('examDate', event.target.value)} /></label></div>}{step === 1 && <div className="form-section"><label className="field"><span>Subjects in your rotation</span><div className="chip-grid">{subjects.map((subject) => <button type="button" className={`choice-chip ${form.subjects.includes(subject) ? 'selected' : ''}`} key={subject} onClick={() => update('subjects', form.subjects.includes(subject) ? form.subjects.filter((item) => item !== subject) : [...form.subjects, subject])}>{form.subjects.includes(subject) && <Check size={14} />}{subject}</button>)}</div></label><label className="field"><span>Daily study goal <strong>{form.dailyHours} hours</strong></span><input type="range" min="1" max="12" value={form.dailyHours} onChange={(event) => update('dailyHours', event.target.value)} /></label></div>}{step === 2 && <div className="form-section"><label className="field"><span>Preferred learning style</span><select value={form.style} onChange={(event) => update('style', event.target.value)}><option>Visual + practice</option><option>Concept first</option><option>Fast revision</option><option>Socratic questions</option></select></label><div className="confidence-list">{form.subjects.map((subject) => <label className="confidence-row" key={subject}><span>{subject}</span><input type="range" min="0" max="100" value={form.confidence?.[subject] ?? 50} onChange={(event) => update('confidence', { ...form.confidence, [subject]: Number(event.target.value) })} /><strong>{form.confidence?.[subject] ?? 50}%</strong></label>)}</div></div>}<div className="onboarding-actions">{step > 0 && <Button variant="ghost" icon={ArrowLeft} onClick={() => setStep(step - 1)}>Back</Button>}{step < 2 ? <Button icon={ArrowRight} onClick={() => { setError(''); setStep(step + 1); }}>Continue</Button> : <><Button variant="secondary" icon={Zap} onClick={() => { save(); navigate('/diagnostic'); }}>Take diagnostic</Button><Button icon={Check} onClick={save}>Save profile</Button></>}</div></Card></div>; }

function ChatPage({ data }) {
  const [conversations, setConversations] = useState(() => storage.get('chat-conversations', [{ id: 'welcome', title: 'Today\'s study session', messages: [defaultMessage], updatedAt: Date.now() }])); const [activeId, setActiveId] = useState(() => storage.get('active-conversation', 'welcome')); const [mode, setMode] = useState(() => storage.get('tutor-mode', 'Tutor')); const [input, setInput] = useState(''); const [typing, setTyping] = useState(false); const [error, setError] = useState(''); const abortRef = useRef(null); const active = conversations.find((conversation) => conversation.id === activeId) || conversations[0]; const update = (next) => { setConversations(next); storage.set('chat-conversations', next); }; const answer = async (text) => { const user = { role: 'user', text, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }; const nextMessages = [...active.messages, user]; const nextConversations = conversations.map((item) => item.id === active.id ? { ...item, messages: nextMessages, title: item.title === 'New conversation' ? text.slice(0, 30) : item.title, updatedAt: Date.now() } : item); update(nextConversations); setInput(''); setTyping(true); setError(''); let response = ''; try { const controller = new AbortController(); abortRef.current = controller; const result = await fetch('http://localhost:11434/api/generate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'llama3.2', prompt: `${mode} tutor. Student mastery: ${JSON.stringify(data.personalization.mastery)}. Question: ${text}`, stream: false }), signal: controller.signal }); if (!result.ok) throw new Error('Ollama unavailable'); response = (await result.json()).response; } catch (requestError) { if (requestError.name !== 'AbortError') response = mode === 'Socratic' ? `Start with two checks: what do you already know about “${text}”, and which definition might apply? Give me your first step, then I’ll reveal a hint.` : mode === 'Explain Simply' ? `In plain language, ${text.replace(/[?!.]+$/, '')} means we connect the rule to one concrete example, then test it with a small variation. Focus on the definition before memorising a shortcut.` : `Let’s make “${text}” manageable. Define the key idea, work one example line by line, and finish with a quick self-check. Your weakest local area is ${data.personalization.weakSubjects[0] || 'your current subject'}, so try linking this question to that foundation.`; } const ai = { role: 'ai', text: response || 'I could not generate a response. Try again.', time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }; update(nextConversations.map((item) => item.id === active.id ? { ...item, messages: [...nextMessages, ai] } : item)); setTyping(false); abortRef.current = null; }; const send = (text = input) => text.trim() && answer(text.trim()); const create = () => { const item = { id: `chat-${Date.now()}`, title: 'New conversation', messages: [defaultMessage], updatedAt: Date.now() }; update([item, ...conversations]); setActiveId(item.id); storage.set('active-conversation', item.id); }; const remove = () => { const remaining = conversations.filter((item) => item.id !== active.id); const fallback = remaining[0] || { id: `chat-${Date.now()}`, title: 'New conversation', messages: [defaultMessage], updatedAt: Date.now() }; update(remaining.length ? remaining : [fallback]); setActiveId(fallback.id); }; const lastAi = [...active.messages].reverse().find((message) => message.role === 'ai'); const copy = () => { navigator.clipboard?.writeText(lastAi?.text || ''); setError('Last answer copied.'); }; return <div className="chat-page"><div className="page-intro"><div><span className="eyebrow">LOCAL AI TUTOR</span><h1>Learn in conversation.</h1><p>Ollama is optional. Demo AI mode stays useful and deterministic offline.</p></div><Badge tone="teal"><span className="status-dot" /> Demo AI fallback</Badge></div><div className="chat-layout"><Card className="conversation-list"><div className="conversation-header"><strong>Conversations</strong><Button variant="icon" icon={Plus} aria-label="New conversation" onClick={create} /></div>{conversations.map((conversation) => <button className={`conversation ${conversation.id === active.id ? 'active' : ''}`} key={conversation.id} onClick={() => { setActiveId(conversation.id); storage.set('active-conversation', conversation.id); }}><span className="conversation-icon"><MessageCircle size={15} /></span><span><strong>{conversation.title}</strong><small>{conversation.messages.length} messages</small></span></button>)}<div className="conversation-footer"><Sparkles size={16} /><small>No API key or account required.</small></div></Card><Card className="chat-window"><div className="chat-toolbar"><div><strong>{active.title}</strong><small><span className="status-dot" /> Ready to help</small></div><div className="mode-select"><span>Mode</span><select value={mode} onChange={(event) => { setMode(event.target.value); storage.set('tutor-mode', event.target.value); }}>{['Tutor', 'Socratic', 'Explain Simply', 'Doubt Solver'].map((item) => <option key={item}>{item}</option>)}</select></div></div><div className="message-scroll">{active.messages.map((message, index) => <motion.div initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} className={`message-row ${message.role}`} key={`${message.time}-${index}`}><div className={`message-avatar ${message.role}`}>{message.role === 'ai' ? <Sparkles size={15} /> : 'ME'}</div><div className="message-body"><div className="message-meta"><strong>{message.role === 'ai' ? 'StudyMate AI' : 'You'}</strong><small>{message.time}</small></div><p>{message.text}</p>{message.role === 'ai' && <button className="copy-button" onClick={() => navigator.clipboard?.writeText(message.text)}><Copy size={13} /> Copy</button>}</div></motion.div>)}{typing && <div className="typing"><LoaderCircle size={16} /> Thinking locally...</div>}</div><div className="suggested-prompts">{['Explain my weakest topic', 'Give me a 10-minute revision sprint', 'Quiz me with one question'].map((prompt) => <button key={prompt} onClick={() => send(prompt)}>{prompt}</button>)}</div><div className="chat-composer"><textarea aria-label="Message your tutor" value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); send(); } }} placeholder="Ask a question..." /><Button icon={typing ? X : Send} disabled={typing || !input.trim()} onClick={() => typing ? abortRef.current?.abort() : send()}>{typing ? 'Cancel' : 'Send'}</Button></div><div className="chat-footer-actions"><button onClick={copy}><Copy size={14} /> Copy last answer</button><button onClick={() => lastAi && send(`Please regenerate this answer: ${lastAi.text}`)}><RotateCcw size={14} /> Regenerate</button><button onClick={() => download(`${active.title.replace(/\s+/g, '-').toLowerCase()}.txt`, active.messages.map((message) => `${message.role}: ${message.text}`).join('\n\n'), 'text/plain')}><Download size={14} /> Export</button><button onClick={remove}><Trash2 size={14} /> Delete</button></div>{error && <div className="inline-notice"><AlertCircle size={14} />{error}</div>}</Card></div></div>; }


function StudyPlan({ data }) { const { tasks, setTasks, sessions, setSessions, personalization, notify } = data; const [view, setView] = useState('Today'); const [editing, setEditing] = useState(null); const [timer, setTimer] = useState(0); const [running, setRunning] = useState(false); const subjects = data.profile.subjects; useEffect(() => { if (!running) return undefined; const interval = setInterval(() => setTimer((value) => value + 1), 1000); return () => clearInterval(interval); }, [running]); const visible = view === 'All Tasks' ? tasks : view === 'Today' ? tasks.filter((task) => task.day === 'Today') : tasks; const saveTask = (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const task = { id: editing?.id || `task-${Date.now()}`, title: String(form.get('title')).trim(), subject: String(form.get('subject')), day: String(form.get('day')), minutes: Number(form.get('minutes')), priority: String(form.get('priority')), done: editing?.done || false }; if (!task.title || !task.minutes) return; setTasks(editing?.id ? tasks.map((item) => item.id === editing.id ? task : item) : [task, ...tasks]); setEditing(null); notify(editing?.id ? 'Task updated.' : 'Task added to your plan.'); }; const finishSession = () => { if (timer < 10) return notify('Complete at least 10 seconds of focus time.'); setSessions([...sessions, { id: `session-${Date.now()}`, minutes: Math.max(1, Math.round(timer / 60)), date: new Date().toISOString() }]); setTimer(0); setRunning(false); notify('Focus session saved to your study history.'); }; return <div><div className="page-intro"><div><span className="eyebrow">YOUR WEEK, DESIGNED</span><h1>A plan you can actually keep.</h1><p>{personalization.dailyTarget} hours daily, prioritising {personalization.weakSubjects[0] || 'your focus subject'}.</p></div><Button icon={Plus} onClick={() => setEditing({})}>Add task</Button></div><Card className="plan-summary"><div><span className="eyebrow">PLAN PROGRESS</span><strong>{tasks.filter((task) => task.done).length} <small>/ {tasks.length} tasks</small></strong></div><ProgressBar value={tasks.length ? tasks.filter((task) => task.done).length / tasks.length * 100 : 0} /><div className="plan-summary-meta"><span>{sessions.length} focus sessions saved</span><span>{tasks.filter((task) => !task.done).length} remaining</span></div></Card><div className="planner-toolbar"><div className="segmented">{['Today', 'This Week', 'All Tasks'].map((item) => <button className={view === item ? 'selected' : ''} key={item} onClick={() => setView(item)}>{item}</button>)}</div><Button variant="secondary" icon={Clock3} onClick={() => setRunning(!running)}>{running ? 'Pause focus' : 'Start focus'}</Button></div><div className="planner-layout"><Card><SectionHeading eyebrow={view.toUpperCase()} title="Study tasks" />{visible.length ? <div className="task-list planner-tasks">{visible.map((task) => <div className={`planner-task ${task.done ? 'done' : ''}`} key={task.id}><button className="task-check" aria-label={`Mark ${task.title} ${task.done ? 'open' : 'complete'}`} onClick={() => setTasks(tasks.map((item) => item.id === task.id ? { ...item, done: !item.done } : item))}>{task.done && <Check size={13} />}</button><div><strong>{task.title}</strong><small><span className="subject-dot" />{task.subject} · {task.day} · {task.minutes || 30} min · {task.priority || 'Medium'}</small></div><button className="icon-button subtle" aria-label="Edit task" onClick={() => setEditing(task)}><Pencil size={15} /></button><button className="icon-button subtle danger" aria-label="Delete task" onClick={() => setTasks(tasks.filter((item) => item.id !== task.id))}><Trash2 size={15} /></button></div>)}</div> : <EmptyState icon={CalendarDays} title="No tasks in this view" text="Add a small, specific task to create momentum." action={<Button icon={Plus} onClick={() => setEditing({})}>Add task</Button>} />}</Card><Card className="pomodoro-card"><SectionHeading eyebrow="FOCUS TIMER" title="Protect one block" /><div className="pomodoro-time">{String(Math.floor(timer / 60)).padStart(2, '0')}:{String(timer % 60).padStart(2, '0')}</div><p>Sessions of 25 minutes are enough to build a repeatable habit.</p><div className="action-row"><Button icon={running ? X : Play} onClick={() => setRunning(!running)}>{running ? 'Pause' : 'Start'}</Button><Button variant="secondary" icon={RotateCcw} onClick={() => { setRunning(false); setTimer(0); }}>Reset</Button><Button variant="secondary" icon={Check} onClick={finishSession}>Complete</Button></div></Card></div>{editing && <Modal title={editing.id ? 'Edit task' : 'Add task'} onClose={() => setEditing(null)}><form className="modal-form" onSubmit={saveTask}><label className="field"><span>Task title</span><input name="title" defaultValue={editing.title || ''} required placeholder="e.g. Revise integration by parts" /></label><label className="field"><span>Subject</span><select name="subject" defaultValue={editing.subject || subjects[0]}>{subjects.map((subject) => <option key={subject}>{subject}</option>)}</select></label><label className="field"><span>Due view</span><select name="day" defaultValue={editing.day || 'Today'}><option>Today</option><option>Tomorrow</option><option>Wednesday</option><option>Thursday</option><option>Friday</option></select></label><label className="field"><span>Estimated minutes</span><input name="minutes" type="number" min="5" max="240" defaultValue={editing.minutes || 30} required /></label><label className="field"><span>Priority</span><select name="priority" defaultValue={editing.priority || 'Medium'}><option>Low</option><option>Medium</option><option>High</option></select></label><Button icon={Check}>{editing.id ? 'Save task' : 'Add task'}</Button></form></Modal>}</div>; }

function Diagnostic({ data }) { const navigate = useNavigate(); const [settings, setSettings] = useState({ exam: data.profile.exam, subject: data.profile.subjects[0] || 'Mathematics' }); const [quiz, setQuiz] = useState(null); const [answers, setAnswers] = useState({}); const [current, setCurrent] = useState(0); const [difficulty, setDifficulty] = useState('Medium'); const [result, setResult] = useState(null); const start = () => { const first = getQuestions({ exam: settings.exam, subject: settings.subject, count: 9, difficulty: 'Adaptive', seed: Date.now() }); setQuiz(first.length ? first : getQuestions({ subject: settings.subject, count: 9 })); setAnswers({}); setCurrent(0); setDifficulty('Medium'); setResult(null); }; const next = () => { const question = quiz[current]; const correct = answers[current] === question.correctAnswer; setDifficulty(getAdaptiveDifficulty({ currentDifficulty: question.difficulty, wasCorrect: correct })); if (current === quiz.length - 1) { const score = Math.round(Object.values(answers).filter((answer, index) => answer === quiz[index]?.correctAnswer).length / quiz.length * 100); const strengths = [...new Set(quiz.filter((item, index) => answers[index] === item.correctAnswer).map((item) => item.topic))]; const weak = [...new Set(quiz.filter((item, index) => answers[index] !== item.correctAnswer).map((item) => item.topic))]; const diagnostic = { score, level: score >= 80 ? 'Strong foundation' : score >= 55 ? 'Building confidence' : 'Foundation first', strengths, weakTopics: weak, date: new Date().toISOString() }; storage.set('diagnostic', diagnostic); setResult(diagnostic); } else setCurrent(current + 1); }; if (result) return <div><div className="page-intro"><div><span className="eyebrow">DIAGNOSTIC COMPLETE</span><h1>{result.level}</h1><p>Your local plan is ready to adapt around this baseline.</p></div><Badge tone="teal">{result.score}% baseline</Badge></div><div className="result-grid"><Card><Trophy size={28} /><h2>{result.score}%</h2><p>Strengths: {result.strengths.join(', ') || 'We have a clear starting point.'}</p><p>Topics to revisit: {result.weakTopics.join(', ') || 'Keep extending your range.'}</p><Button icon={CalendarDays} onClick={() => navigate('/study-plan')}>Apply my plan</Button></Card><Card><SectionHeading eyebrow="NEXT BEST MOVE" title="A focused week" /><p>Start with {result.weakTopics[0] || 'your lowest-confidence subject'} for {data.personalization.dailyTarget} hours per day, then retake a short set to measure improvement.</p><Button variant="secondary" icon={ListChecks} onClick={() => navigate('/quiz')}>Practice now</Button></Card></div></div>; if (!quiz) return <div><div className="page-intro"><div><span className="eyebrow">BASELINE CHECK</span><h1>Find your starting line.</h1><p>A local 9-question adaptive check adjusts difficulty after every answer.</p></div></div><Card className="quiz-setup"><div className="form-grid quiz-fields"><label className="field"><span>Exam</span><select value={settings.exam} onChange={(event) => setSettings({ ...settings, exam: event.target.value })}>{['JEE', 'NEET', 'CAT', 'UPSC', 'CBSE Board'].map((exam) => <option key={exam}>{exam}</option>)}</select></label><label className="field"><span>Subject</span><select value={settings.subject} onChange={(event) => setSettings({ ...settings, subject: event.target.value })}>{data.profile.subjects.map((subject) => <option key={subject}>{subject}</option>)}</select></label></div><Button icon={Play} onClick={start}>Begin diagnostic</Button></Card></div>; const question = quiz[current]; return <div><div className="page-intro"><div><span className="eyebrow">QUESTION {current + 1} OF {quiz.length}</span><h1>Show us how you think.</h1><p>Adaptive difficulty is now {difficulty}. Choose the best answer.</p></div></div><Card className="quiz-runner"><ProgressBar value={(current + 1) / quiz.length * 100} /><Badge tone="indigo">{question.topic}</Badge><h2>{question.question}</h2><div className="answer-options">{question.options.map((option, index) => <button className={`answer-option ${answers[current] === index ? 'selected' : ''}`} key={option} onClick={() => setAnswers({ ...answers, [current]: index })}><span>{String.fromCharCode(65 + index)}</span>{option}</button>)}</div><Button disabled={answers[current] === undefined} icon={current === quiz.length - 1 ? CheckCircle2 : ArrowRight} onClick={next}>{current === quiz.length - 1 ? 'See results' : 'Next question'}</Button></Card></div>; }

function QuizPage({ data }) { const [params] = useSearchParams(); const [settings, setSettings] = useState({ exam: 'All exams', subject: 'All subjects', topic: params.get('topic') || 'All topics', difficulty: 'Adaptive', count: 5, timed: false }); const [quiz, setQuiz] = useState(null); const [answers, setAnswers] = useState({}); const [current, setCurrent] = useState(0); const [submitted, setSubmitted] = useState(false); const [review, setReview] = useState('All'); const [error, setError] = useState(''); const start = () => { const next = getQuestions({ ...settings, difficulty: settings.difficulty === 'Adaptive' ? data.personalization.recommendedDifficulty : settings.difficulty, count: Number(settings.count), seed: Date.now() }); if (!next.length) return setError('No local questions match these filters. Try a broader topic.'); setQuiz(next); setAnswers({}); setCurrent(0); setSubmitted(false); }; const finish = () => { const score = Math.round(quiz.filter((question, index) => answers[index] === question.correctAnswer).length / quiz.length * 100); const attempt = { id: `attempt-${Date.now()}`, title: `${settings.subject} practice`, subject: settings.subject, score, total: quiz.length, date: new Date().toISOString(), questions: quiz.map((question, index) => ({ ...question, selected: answers[index], correct: answers[index] === question.correctAnswer })) }; data.setAttempts([attempt, ...data.attempts]); setSubmitted(true); }; if (!quiz) return <div><div className="page-intro"><div><span className="eyebrow">ADAPTIVE PRACTICE</span><h1>Turn practice into progress.</h1><p>Questions adjust to your confidence and reveal what to revisit next.</p></div><Badge tone="amber"><Zap size={13} /> Local question bank</Badge></div><Card className="quiz-setup"><div className="form-grid quiz-fields"><label className="field"><span>Exam</span><select value={settings.exam} onChange={(event) => setSettings({ ...settings, exam: event.target.value })}><option>All exams</option>{[...new Set(questionBank.map((item) => item.exam))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span>Subject</span><select value={settings.subject} onChange={(event) => setSettings({ ...settings, subject: event.target.value })}><option>All subjects</option>{[...new Set(questionBank.map((item) => item.subject))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span>Topic</span><select value={settings.topic} onChange={(event) => setSettings({ ...settings, topic: event.target.value })}><option>All topics</option>{[...new Set(questionBank.map((item) => item.topic))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span>Difficulty</span><select value={settings.difficulty} onChange={(event) => setSettings({ ...settings, difficulty: event.target.value })}>{['Adaptive', 'Easy', 'Medium', 'Hard'].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span>Questions</span><select value={settings.count} onChange={(event) => setSettings({ ...settings, count: event.target.value })}>{[3, 5, 8, 10].map((item) => <option key={item}>{item}</option>)}</select></label></div>{error && <div className="form-error"><AlertCircle size={15} />{error}</div>}<Button icon={Play} onClick={start}>Start set</Button></Card></div>; if (submitted) { const score = Math.round(quiz.filter((question, index) => answers[index] === question.correctAnswer).length / quiz.length * 100); const filtered = quiz.map((question, index) => ({ question, index })).filter(({ question, index }) => review === 'All' || (review === 'Correct' ? answers[index] === question.correctAnswer : answers[index] !== question.correctAnswer && (review !== 'Careless Mistake' || question.commonMistakeType === 'careless mistake'))); return <div><div className="page-intro"><div><span className="eyebrow">SET COMPLETE</span><h1>{score >= 80 ? 'Excellent momentum.' : score >= 50 ? 'A useful checkpoint.' : 'A clear next step.'}</h1><p>{score}% score. Review your errors while the reasoning is fresh.</p></div><Badge tone={score >= 70 ? 'teal' : 'amber'}>{score >= 80 ? 'Strong' : score >= 50 ? 'Building' : 'Revisit concepts'}</Badge></div><Card className="review-card"><div className="segmented">{['All', 'Correct', 'Incorrect', 'Careless Mistake'].map((item) => <button className={review === item ? 'selected' : ''} key={item} onClick={() => setReview(item)}>{item}</button>)}</div>{filtered.map(({ question, index }) => <div className="review-item" key={question.id}><div><Badge tone={answers[index] === question.correctAnswer ? 'teal' : 'amber'}>{answers[index] === question.correctAnswer ? 'Correct' : question.commonMistakeType}</Badge><h3>{question.question}</h3><p>{question.explanation}</p></div></div>)}</Card><Button variant="secondary" icon={RotateCcw} onClick={() => setQuiz(null)}>New set</Button></div>; } const question = quiz[current]; return <div><div className="page-intro"><div><span className="eyebrow">QUESTION {current + 1} OF {quiz.length}</span><h1>Stay curious, stay precise.</h1></div></div><Card className="quiz-runner"><div className="question-meta"><Badge tone="indigo">{question.subject}</Badge><Badge>{question.difficulty}</Badge><span>{question.topic}</span></div><h2>{question.question}</h2><div className="answer-options">{question.options.map((option, index) => <button className={`answer-option ${answers[current] === index ? 'selected' : ''}`} key={option} onClick={() => setAnswers({ ...answers, [current]: index })}><span>{String.fromCharCode(65 + index)}</span>{option}{answers[current] === index && <Check size={16} />}</button>)}</div><div className="quiz-controls"><Button variant="ghost" icon={ChevronLeft} disabled={current === 0} onClick={() => setCurrent(current - 1)}>Previous</Button>{current < quiz.length - 1 ? <Button icon={ChevronRight} onClick={() => setCurrent(current + 1)}>Next</Button> : <Button icon={CheckCircle2} onClick={finish}>Submit set</Button>}</div></Card></div>; }

function Analytics({ data }) { const scoreData = data.attempts.length ? data.attempts.slice(0, 7).reverse().map((attempt, index) => ({ day: `Set ${index + 1}`, score: attempt.score })) : [{ day: 'Mon', score: 64 }, { day: 'Tue', score: 72 }, { day: 'Wed', score: 68 }, { day: 'Thu', score: 81 }, { day: 'Fri', score: 78 }]; const mastery = Object.entries(data.personalization.mastery).map(([subject, score]) => ({ subject: subject.slice(0, 10), score })); return <div><div className="page-intro"><div><span className="eyebrow">YOUR SIGNALS, MADE USEFUL</span><h1>See what is getting stronger.</h1><p>Everything here is calculated locally from your practice and focus sessions.</p></div><Button variant="secondary" icon={Download} onClick={() => download('studymate-report.json', JSON.stringify({ personalization: data.personalization, attempts: data.attempts }, null, 2))}>Export report</Button></div><div className="analytics-grid"><Card className="wide-chart"><SectionHeading eyebrow="MASTERY BY SUBJECT" title="Your current signal" /><ResponsiveContainer width="100%" height={240}><RadarChart data={mastery}><PolarGrid /><PolarAngleAxis dataKey="subject" /><Radar dataKey="score" stroke="#5b5bf7" fill="#5b5bf7" fillOpacity={.25} /></RadarChart></ResponsiveContainer></Card><Card className="score-chart"><SectionHeading eyebrow="PRACTICE QUALITY" title="Quiz scores" /><ResponsiveContainer width="100%" height={210}><AreaChart data={scoreData}><XAxis dataKey="day" hide /><YAxis domain={[0, 100]} hide /><Tooltip /><Area type="monotone" dataKey="score" stroke="#2dd4bf" fill="#2dd4bf" fillOpacity={.18} /></AreaChart></ResponsiveContainer></Card><Card className="wide-chart"><SectionHeading eyebrow="RECOMMENDATION" title={data.personalization.nextAction} /><p className="recommendation-copy">Weak topics: {data.personalization.weakTopics.map((topic) => `${topic.topic} (${topic.score}%)`).join(', ') || 'Complete a few more questions to reveal topic patterns.'}</p><div className="analytics-stats"><strong>{data.personalization.focusedMinutes}m</strong><span>focused study time</span><strong>{data.personalization.completedMinutes}m</strong><span>task time completed</span></div></Card><Card className="score-chart"><SectionHeading eyebrow="RECENT QUIZZES" title={`${data.attempts.length} saved attempts`} />{data.attempts.slice(0, 4).map((attempt) => <div className="recent-row" key={attempt.id}><span>{attempt.title}</span><Badge tone={attempt.score >= 70 ? 'teal' : 'amber'}>{attempt.score}%</Badge></div>)}{!data.attempts.length && <EmptyState icon={ListChecks} title="No attempts yet" text="Your first local quiz will appear here." />}</Card></div></div>; }

function KnowledgeMap({ data }) { const [selected, setSelected] = useState(curriculum[2]); const [exam, setExam] = useState('JEE Mathematics'); const navigate = useNavigate(); const statuses = data.personalization.weakTopics.map((topic) => topic.topic); const nodes = curriculum.map((node) => ({ ...node, status: statuses.includes(node.title) ? 'weak' : node.status })); return <div><div className="page-intro"><div><span className="eyebrow">CURRICULUM GRAPH</span><h1>See the shape of your syllabus.</h1><p>Prerequisites turn a long syllabus into the next useful concept.</p></div><select className="compact-select" value={exam} onChange={(event) => setExam(event.target.value)}><option>JEE Mathematics</option></select></div><div className="map-layout"><Card className="map-card"><svg className="curriculum-svg" viewBox="0 0 800 400" role="img" aria-label="JEE mathematics prerequisite map"><path d="M145 120 H265 M335 120 H455 M525 120 H645 M335 145 V275 M525 145 V275 M645 145 V275" className="map-edge" />{nodes.map((node) => <g key={node.id} className="map-node" tabIndex="0" onClick={() => setSelected(node)} onKeyDown={(event) => event.key === 'Enter' && setSelected(node)}><circle cx={node.x} cy={node.y} r="31" className={`node-circle ${node.status}`} /><text x={node.x} y={node.y + 5} textAnchor="middle" className="node-icon">{node.status === 'locked' ? '×' : node.status === 'completed' ? '✓' : node.status === 'weak' ? '!' : '•'}</text><text x={node.x} y={node.y + 57} textAnchor="middle" className="node-title">{node.title}</text></g>)}</svg><div className="map-legend"><span><i className="map-dot completed" /> Completed</span><span><i className="map-dot current" /> Available</span><span><i className="map-dot weak" /> Weak</span><span><i className="map-dot locked" /> Locked</span></div></Card><Card className="concept-panel"><div className={`concept-status ${selected.status}`}><span className="status-dot" /> {selected.status}</div><h2>{selected.title}</h2><p>{selected.detail}</p><div className="concept-meta"><span>Prerequisites</span><div>{selected.prerequisites.length ? selected.prerequisites.map((id) => <Badge key={id}>{curriculum.find((item) => item.id === id)?.title}</Badge>) : <Badge tone="teal">None</Badge>}</div></div><p className="recommendation-copy">Recommended action: {selected.status === 'locked' ? 'Complete the prerequisite path first.' : `Take a ${data.personalization.recommendedDifficulty.toLowerCase()} practice set.`}</p><Button icon={Play} disabled={selected.status === 'locked'} onClick={() => navigate(`/quiz?topic=${encodeURIComponent(selected.title)}`)}>Start practice</Button></Card></div></div>; }

function DoubtSolver() { const [file, setFile] = useState(null); const [text, setText] = useState(''); const [loading, setLoading] = useState(false); const [solution, setSolution] = useState(''); const process = (selected) => { if (!selected) return; if (selected.size > 10 * 1024 * 1024) return setSolution('This file is larger than 10 MB. Choose a smaller local file.'); setFile(selected); setLoading(true); if (selected.type === 'text/plain') { const reader = new FileReader(); reader.onload = (event) => { setText(String(event.target.result)); setLoading(false); }; reader.onerror = () => { setSolution('Text extraction failed. You can still type the question below.'); setLoading(false); }; reader.readAsText(selected); } else { setTimeout(() => { setText(`Document ready: ${selected.name}\n\nType or paste the exact question here for a reliable local step-by-step solution.`); setLoading(false); }, 500); } }; return <div><div className="page-intro"><div><span className="eyebrow">FROM PAGE TO UNDERSTANDING</span><h1>Untangle a tricky doubt.</h1><p>Upload a text, image, or PDF, then edit the extracted prompt before solving.</p></div><Badge tone="teal"><FileText size={13} /> Local processing</Badge></div><div className="doubt-grid"><Card className="upload-card"><div className="upload-zone" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); process(event.dataTransfer.files[0]); }}><input id="file-input" type="file" accept="image/*,.pdf,.txt" onChange={(event) => process(event.target.files[0])} /><label htmlFor="file-input"><div className="upload-icon"><Upload size={22} /></div><strong>{file ? file.name : 'Drop a question here'}</strong><span>{file ? 'File ready to review' : 'or click to browse from your device'}</span><small>TXT works instantly; PDF and image text can be edited after local extraction.</small></label></div>{loading && <div className="loading-state"><LoaderCircle size={17} /> Reading local file...</div>}<label className="field"><span>Extracted question</span><textarea rows="8" value={text} onChange={(event) => setText(event.target.value)} placeholder="Paste a question or upload a file first..." /></label><Button icon={Sparkles} disabled={loading || !text.trim()} onClick={() => setSolution(`1. Identify what is known and what the question asks.\n\n2. Name the relevant definition or formula before substituting values.\n\n3. Work one transformation at a time and check units or assumptions.\n\nLocal tutor prompt: explain why your first step is valid, then compare it with the final condition.`)}>Solve step by step</Button></Card><Card className="solution-card"><SectionHeading eyebrow="WORKED SUPPORT" title="Your solution path" />{solution ? <div className="solution-text">{solution.split('\n').map((line, index) => <p key={index}>{line || ' '}</p>)}</div> : <EmptyState icon={HelpCircle} title="Your reasoning will appear here" text="Upload a question, edit the extracted text, and ask for a clear sequence." />}</Card></div></div>; }

function Settings({ data }) { const [form, setForm] = useState(data.profile); const [saved, setSaved] = useState(false); const [confirm, setConfirm] = useState(false); const fileRef = useRef(null); const save = () => { if (!form.name.trim() || !form.examDate) return; data.setProfile(form); storage.set('profile', form); setSaved(true); setTimeout(() => setSaved(false), 1800); }; const loadDemo = () => { data.setTasks([...data.tasks, ...demoTasks.filter((demo) => !data.tasks.some((task) => task.id === demo.id))]); data.setAttempts([...data.attempts, ...demoAttempts.filter((demo) => !data.attempts.some((attempt) => attempt.id === demo.id))]); data.notify('Demo data merged without duplicates.'); }; const exportAll = () => download('studymate-data.json', JSON.stringify(collectData(), null, 2)); const importFile = (event) => { const file = event.target.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const result = importData(JSON.parse(reader.result)); if (!result.valid) throw new Error(result.error); data.notify('Data imported. Refreshing your local workspace.'); setTimeout(() => window.location.reload(), 500); } catch (error) { data.notify(error.message || 'This file could not be imported.'); } }; reader.readAsText(file); event.target.value = ''; }; const reset = () => { resetStudyMateData(); setConfirm(false); window.location.href = '/onboarding'; }; return <div><div className="page-intro"><div><span className="eyebrow">YOUR WORKSPACE</span><h1>Settings that stay simple.</h1><p>Everything is saved locally on this device.</p></div>{saved && <Badge tone="teal"><Check size={13} /> Saved</Badge>}</div><div className="settings-layout"><Card><SectionHeading eyebrow="PROFILE" title="Student profile" /><div className="settings-form"><label className="field"><span>Name</span><input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></label><label className="field"><span>Target exam</span><select value={form.exam} onChange={(event) => setForm({ ...form, exam: event.target.value })}>{['JEE', 'NEET', 'CAT', 'UPSC', 'CBSE Board', 'Custom'].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span>Exam date</span><input type="date" value={form.examDate} onChange={(event) => setForm({ ...form, examDate: event.target.value })} /></label><label className="field"><span>Daily goal</span><input type="number" min="1" max="12" value={form.dailyHours} onChange={(event) => setForm({ ...form, dailyHours: event.target.value })} /></label></div><Button icon={Check} onClick={save}>Save changes</Button></Card><Card><SectionHeading eyebrow="DATA CONTROLS" title="Your local data" /><div className="data-summary"><span>Profile <strong>1</strong></span><span>Chats <strong>{storage.get('chat-conversations', []).length}</strong></span><span>Quiz attempts <strong>{data.attempts.length}</strong></span><span>Tasks <strong>{data.tasks.length}</strong></span><span>Focus sessions <strong>{data.sessions.length}</strong></span></div><div className="data-actions"><Button variant="secondary" icon={Download} onClick={exportAll}>Export my data</Button><Button variant="secondary" icon={Upload} onClick={() => fileRef.current?.click()}>Import my data</Button><input ref={fileRef} hidden type="file" accept="application/json,.json" onChange={importFile} /><Button variant="secondary" icon={Sparkles} onClick={loadDemo}>Load demo data</Button><Button variant="danger" icon={Trash2} onClick={() => setConfirm(true)}>Reset my data</Button></div></Card><Card><SectionHeading eyebrow="PRIVACY" title="Local by default" /><p>Your data is stored locally in this browser. No account or paid service is used.</p><div className="connection-row"><div className="connection-icon"><Zap size={19} /></div><div><strong>Demo AI mode active</strong><small>Optional Ollama endpoint: localhost:11434</small></div><Badge tone="teal">No API key</Badge></div></Card></div>{confirm && <Modal title="Reset StudyMate data?" onClose={() => setConfirm(false)}><p>This removes only StudyMate keys from this browser. Your other site data is untouched.</p><div className="modal-actions"><Button variant="ghost" onClick={() => setConfirm(false)}>Keep data</Button><Button variant="danger" icon={Trash2} onClick={reset}>Reset everything</Button></div></Modal>}</div>; }

class ErrorBoundary extends Component { state = { hasError: false }; static getDerivedStateFromError() { return { hasError: true }; } render() { return this.state.hasError ? <div className="error-fallback"><AlertCircle size={24} /><h1>Something needs a refresh.</h1><p>Your local data is safe. Reload the page to continue.</p><Button onClick={() => window.location.reload()}>Reload app</Button></div> : this.props.children; } }

function App() { const data = useAppData(); return <BrowserRouter><ErrorBoundary><Toast message={data.toast} onClose={() => data.notify('')} /><Routes><Route path="/onboarding" element={<Onboarding data={data} />} /><Route path="/diagnostic" element={<AppShell profile={data.profile}><Diagnostic data={data} /></AppShell>} /><Route path="*" element={<AppShell profile={data.profile}><Routes><Route path="/" element={<Dashboard data={data} />} /><Route path="/chat" element={<ChatPage data={data} />} /><Route path="/study-plan" element={<StudyPlan data={data} />} /><Route path="/quiz" element={<QuizPage data={data} />} /><Route path="/doubt-solver" element={<DoubtSolver />} /><Route path="/analytics" element={<Analytics data={data} />} /><Route path="/knowledge-map" element={<KnowledgeMap data={data} />} /><Route path="/settings" element={<Settings data={data} />} /></Routes></AppShell>} /></Routes></ErrorBoundary></BrowserRouter>; }
export default App;
